let dotNetRef;
let timerId;
let isIdle = false;
const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];

function onActivity() {
    resetTimer();
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnStateChanged", false);
    }
}

function resetTimer() {
    clearTimeout(timerId);
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnStateChanged", true);
    }, window._activityTimeoutMs);
}

export function init(ref, timeoutSeconds) {
    dotNetRef = ref;
    window._activityTimeoutMs = timeoutSeconds * 1000;
    isIdle = false;

    for (const e of events) {
        document.addEventListener(e, onActivity, { passive: true });
    }
    resetTimer();
}

export function dispose() {
    clearTimeout(timerId);
    for (const e of events) {
        document.removeEventListener(e, onActivity);
    }
    dotNetRef = null;
}

